def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    # Find regularly spaced grid separators: rows/columns mostly of the
    # dominant grid color.
    freq = Counter(v for row in grid for v in row)
    frame = freq.most_common(1)[0][0]
    rs = [r for r in range(h) if sum(x == frame for x in grid[r]) > w // 2]
    cs = [c for c in range(w) if sum(grid[r][c] == frame for r in range(h)) > h // 2]

    # The separator intersections encode the reduced image.
    if not rs or not cs:
        return grid
    other = Counter(v for row in grid for v in row if v != frame)
    background = other.most_common(1)[0][0] if other else frame
    out = [[grid[r][c] if grid[r][c] != frame else background for c in cs]
           for r in rs]

    # Remove the empty outer border while retaining interior background cells.
    while out and all(v == background for v in out[0]):
        out.pop(0)
    while out and all(v == background for v in out[-1]):
        out.pop()
    if out:
        while all(row[0] == background for row in out):
            for row in out:
                row.pop(0)
        while all(row[-1] == background for row in out):
            for row in out:
                row.pop()
    return out
